('Dispatch Notification','2026-11-10 10:02:55.189528','2026-11-10 10:02:55.189528','Administrator','Administrator',0,0,'Your order is out for delivery!',NULL,0,NULL,'<h1>Dispatch Notification</h1>\n<h3>Details:</h3>\n<table class=\"table table-bordered small\" style=\"max-width:500px\">\n    <tbody>\n        <tr>\n            <td>Customer\'s Name</td>\n            <td>{{ customer }}</td>\n        </tr>\n        <tr>\n            <td>Contact\'s Name</td>\n            <td>{{ first_name }} {{ last_name }}</td>\n        </tr>\n        <tr>\n            <td>Address Name</td>\n            <td>{{ address }}</td>\n        </tr>\n        <tr>\n            <td>Address Details</td>\n            <td>{{ customer_address }}</td>\n        </tr>\n        <tr>\n            <td>Order Number</td>\n            <td>{{ delivery_note }}</td>\n        </tr>\n        <tr>\n            <td>Order Total</td>\n            <td>{{ grand_total }}</td>\n        </tr>\n        <tr>\n            <td>Departure Time</td>\n            <td>{{ departure_time }}</td>\n        </tr>\n        <tr>\n            <td>Estimated Arrival</td>\n            <td>{{ estimated_arrival }}</td>\n        </tr>\n        <tr>\n            <td>Driver\'s Name</td>\n            <td>{{ driver_name }}</td>\n        </tr>\n        <tr>\n            <td>Driver\'s Number</td>\n            <td>{{ cell_number }}</td>\n        </tr>\n        <tr>\n            <td>Vehicle Number</td>\n            <td>{{ vehicle }}</td>\n        </tr>\n    </tbody>\n</table>\n',NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `tabEmail Template` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
