('Create Accounting Purchase Invoice','2026-10-04 01:25:22.673945','2026-10-04 01:39:31.631983','Administrator','Administrator',0,0,'Enter a supplier\'s bill',0,0,'It posts the expense, and what you owe the supplier, to your ledger. See [Purchase Invoice](https://docs.frappe.io/erpnext/user/manual/en/purchase-invoice).','https://www.youtube.com/watch?v=Cb4gYZuV60k','Create Entry','Create Purchase Invoice','Purchase Invoice',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Asset Category','2026-02-23 20:50:50.211884','2026-10-04 01:52:52.469995','Administrator','Administrator',0,1,'Set up an asset category',0,0,'Computers, vehicles, furniture: how each kind depreciates, and which accounts it posts to. See [Asset Category](https://docs.frappe.io/erpnext/user/manual/en/asset-category).',NULL,'Create Entry','Create Asset Category','Asset Category',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Asset Item','2026-02-23 20:52:40.135614','2026-10-04 01:52:52.529058','Administrator','Administrator',0,1,'Add an asset item',0,0,'The kind of thing you own, marked as a fixed asset. See [Item](https://docs.frappe.io/erpnext/user/manual/en/item).',NULL,'Create Entry','Add Item','Item',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'{\n    \"is_fixed_asset\": 1,\n    \"is_stock_item\": 0\n}',NULL,NULL,NULL,NULL),
('Create Asset Maintenance','2026-10-04 01:52:52.539131','2026-10-04 01:52:52.539131','Administrator','Administrator',0,0,'Schedule its upkeep',0,0,'Servicing, inspections and calibration, with reminders to the team doing it. See [Asset Maintenance](https://docs.frappe.io/erpnext/user/manual/en/asset-maintenance).',NULL,'Create Entry','Create Asset Maintenance','Asset Maintenance',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Asset Movement','2026-10-04 01:52:52.537909','2026-10-04 01:52:52.537909','Administrator','Administrator',0,0,'Hand it to a person or place',0,0,'Record who has it and where it is, so you always know. See [Asset Movement](https://docs.frappe.io/erpnext/user/manual/en/asset-movement).',NULL,'Create Entry','Create Asset Movement','Asset Movement',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Bill of Materials','2026-02-20 13:31:41.740588','2026-10-04 01:49:02.870272','Administrator','Administrator',0,0,'Write its bill of materials',0,0,'The raw materials, and how much of each, that go into one unit of your product. Submit it to use it in production. See [BOM](https://docs.frappe.io/erpnext/user/manual/en/bill-of-materials).\n\nSending some of the work to a supplier? See [Subcontracting](https://docs.frappe.io/erpnext/user/manual/en/subcontracting).',NULL,'Create Entry','Create BOM','BOM',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Buying Item','2026-10-04 01:42:03.855747','2026-10-04 01:42:03.855747','Administrator','Administrator',0,0,'Add an item you buy',0,0,'Goods or services you buy from suppliers. See [Item](https://docs.frappe.io/erpnext/user/manual/en/item).','https://www.youtube.com/watch?v=oSYESI-EVCI','Create Entry','Add Item','Item',NULL,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'{\n    \"is_purchase_item\": 1\n}',NULL,NULL,NULL,NULL),
