('Create Delivery Note','2026-02-20 13:42:13.571273','2026-10-04 01:45:40.806158','Administrator','Administrator',0,4,'Ship to a customer',0,0,'Stock goes down as the goods leave, and the invoice can be made from the delivery. See [Delivery Note](https://docs.frappe.io/erpnext/user/manual/en/delivery-note).','https://www.youtube.com/watch?v=sNHanAI_X-I','Create Entry','Create Delivery Note','Delivery Note',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Create Existing Asset','2026-02-23 20:54:25.961869','2026-10-04 01:52:52.532495','Administrator','Administrator',0,3,'Record an asset you already own',0,0,'Something you bought before using ERPNext, with what you paid, where it is, and how much has already depreciated. See [Asset](https://docs.frappe.io/erpnext/user/manual/en/asset).',NULL,'Create Entry','Add Asset','Asset',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'{\n    \"asset_type\": \"Existing Asset\"\n}',NULL,NULL,NULL,NULL),
