('Invite Users','2026-02-24 18:04:21.585575','2026-10-04 03:16:15.287009','Administrator','Administrator',0,0,'Invite your team',0,0,'Add the people you work with and choose what they can see.',NULL,'Create Entry','Add User','User',NULL,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Move Stock','2026-10-04 01:45:40.809249','2026-10-04 01:45:40.809249','Administrator','Administrator',0,0,'Move stock between warehouses',0,0,'From the store to the shop floor, or between branches. See [Stock Entry](https://docs.frappe.io/erpnext/user/manual/en/stock-entry).','https://www.youtube.com/watch?v=QcJbxG74PoU','Create Entry','Create Stock Entry','Stock Entry',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'{\n    \"purpose\": \"Material Transfer\",\n    \"stock_entry_type\": \"Material Transfer\"\n}',NULL,NULL,NULL,NULL),
('Open Banking','2026-10-04 01:25:22.677250','2026-10-04 01:33:32.465649','Administrator','Administrator',0,0,'Match your bank statement',0,0,'Import a statement from your bank and pair each line with a payment, so your books agree with it. See [Bank Reconciliation](https://docs.frappe.io/erpnext/user/manual/en/bank-reconciliation).',NULL,'Go to Page','Open Banking',NULL,NULL,0,0,NULL,0,NULL,NULL,NULL,NULL,'/banking',NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Pay Supplier','2026-10-04 00:49:20.654299','2026-10-04 01:42:03.961861','Administrator','Administrator',0,0,'Pay your supplier',0,0,'It clears their bill and takes the money out of your bank or cash account. See [Payment Entry](https://docs.frappe.io/erpnext/user/manual/en/payment-entry).','https://www.youtube.com/watch?v=oetlenfOAJ8','Create Entry','Create Payment Entry','Payment Entry',NULL,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'{\n    \"payment_type\": \"Pay\",\n    \"party_type\": \"Supplier\"\n}',NULL,NULL,NULL,NULL),
('Review Taxes','2026-10-04 01:44:23.578444','2026-10-04 01:44:23.578444','Administrator','Administrator',0,0,'Review your taxes',0,0,'The taxes that fill in on every invoice. We added your country\'s where we had them; check the rates match what you charge. Purchase taxes live in [Purchase Taxes and Charges Template](/desk/purchase-taxes-and-charges-template). See [Setting Up Taxes](https://docs.frappe.io/erpnext/user/manual/en/setting-up-taxes).','https://www.youtube.com/watch?v=DWKb9Z3KbBU','Go to Page','Open Sales Taxes and Charges Template',NULL,NULL,0,0,NULL,0,NULL,NULL,NULL,NULL,'List/Sales Taxes and Charges Template',NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
