ight: 700;\n		}\n\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-16 {\n			margin-top: 16px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mw-400 {\n			max-width: 400px;\n		}\n\n		.items-table,\n		.tax-table {\n			width: 100%;\n			border-collapse: separate;\n			border-spacing: 0;\n			border-radius: 10px;\n			overflow: hidden;\n		}\n\n		.items-table td,\n		.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		.items-table thead td,\n		.tax-table thead td {\n			color: #7c7c7c !important;\n		}\n		.items-table thead tr:first-of-type td,\n		.tax-table thead tr:first-of-type td {\n			border-bottom: none;\n		}\n\n		.items-table thead tr:first-child td:first-child,\n		.tax-table thead tr:first-child td:first-child {\n			border-top-left-radius: 10px;\n			border-bottom-left-radius: 10px;\n		}\n		.items-table thead tr:first-child td:last-child,\n		.tax-table thead tr:first-child td:last-child {\n			border-top-right-radius: 10px;\n			border-bottom-right-radius: 10px;\n		}\n\n		.in-words {\n			color: #171717 !important;\n			max-width: 400px;\n			word-wrap: break-word;\n			line-height: 1.5;\n			font-size: 12px;\n		}\n\n		.row-divider {\n			border-bottom: 1px solid #e9e9e9;\n		}\n\n		.highlight-bg {\n			background: #f8f8f8;\n		}\n\n		.info-card {\n			margin-top: 40px;\n			color: #7c7c7c;\n		}\n\n		.info-text {\n			margin-bottom: 12px;\n		}\n\n		.print-format {\n			color: #171717;\n			font-size: 14px;\n			font-style: normal;\n			font-weight: 420;\n			line-height: 21px;\n			padding: 0px !important;\n			margin-left: 0mm !important;\n			margin-right: 0mm !important;\n		}\n\n		.letter-head-footer {\n			margin-top: 0px !important;\n		}\n\n		.print-format-body td {\n			padding: 8px 8px !important;\n		}\n\n		.tax-table td,\n		.items-table td {\n			height: auto !important;\n		}\n\n		.tax-table thead td,\n		.items-table thead td {\n			height: 32px;\n		}\n\n		.item-img td {\n			border: none !important;\n			padding: 0px !important;\n		}\n	</style>\n\n	<div class=\"print-format-body\">\n		<table class=\"info-table col-xs-12\" style=\"width: 100%; margin-left: 12px\">\n			<tr>\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Customer Name:\") }}</div>\n						<div class=\"info-text\">{{ _(\"Address:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.customer_name }}</div>\n						<div class=\"info-text\">\n        					{% if doc.customer_address %}\n        						{% set customer_address = frappe.db.get_value(\"Address\", doc.customer_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n        						{{ customer_address.address_line1 or \"\" }}<br>\n        						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}\n        						{{ customer_address.city or \"\" }} {{ customer_address.state or \"\" }} {{ customer_address.pincode or \"\" }} {{ customer_address.country or \"\" }}<br>\n        					{% endif %}\n						</div>\n\n					</div>\n				</td>\n\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Delivery Note:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.name }}</div>\n					</div>\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Delivery Date:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ frappe.utils.format_date(doc.posting_date) }}</div>\n					</div>\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Status:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.status }}</div>\n					</div>\n				</td>\n			</tr>\n		</table>\n\n		<!-- Items Table -->\n		{% set item_naming_by = frappe.db.get_single_value(\"Stock Settings\", \"item_naming_by\") %}\n		<table class=\"items-table mt-15\">\n			<thead class=\"highlight-bg\">\n				<tr>\n					<td class=\"	text-center\">{{ _(\"No\") }}</td>\n					<td class=\"text-left\">{{ _(\"Item\") }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ _(\"Item Code\") }}</td>\n					{% endif %}\n					<td class=\"text-right\">{{ _(\"Quantity\") }}</td>\n					<td class=\"text-right\">{{ _(\"Rate\") }}</td>\n					<td class=\"text-right\">{{ _(\"Amount\") }}</td>\n				</tr>\n			</thead>\n			<tbody>\n				{% for item in doc.items %}\n				<tr>\n					<td class=\"text-center\">{{ loop.index }}</td>\n					<td class=\"text-left\">\n						<table class=\"item-img\" style=\"border-collapse: collapse\">\n							<tr>\n								{% if item.image %}\n								<td class=\"no-style\" style=\"border-radius: 6px; vertical-align: middle\">\n									<img\n										src=\"{{ item.image | e }}\"\n										alt=\"{{ item.item_name | e }}\"\n										style=\"\n											border-radius: 6px;\n											height: 24px;\n											width: 24px !important;\n											margin-right: 8px;\n                                            vertical-align: middle;\n										\"\n									/>\n								</td>\n								{% endif %}\n								<td\n									class=\"no-style\"\n									style=\"vertical-align: middle !important; padding: 0 !important\"\n								>\n									{{ item.item_name }}\n								</td>\n							</tr>\n						</table>\n					</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ item.item_code }}</td>\n					{% endif %}\n\n					<td class=\"text-right\">{{ item.get_formatted(\"qty\", 0) }} {{ item.uom }}</td>\n					<td class=\"text-right\">{{ item.get_formatted(\"net_rate\", doc) }}</td>\n					<td class=\"text-right\">{{ item.get_formatted(\"net_amount\", doc) }}</td>\n				</tr>\n				{% endfor %}\n			</tbody>\n		</table>\n\n		<div class=\"test\" style=\"float: right; margin-top: 15px; margin-bottom: 5px;\">\n			<table style=\"width: 100%; border-collapse: collapse\">\n				<tr class=\"row-divider\">\n					<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">{{ _(\"Sub Total:\") }}</td>\n					<td class=\"text-right\">{{ doc.get_formatted(\"total\", doc) }}</td>\n				</tr>\n\n				{%- if doc.apply_discount_on == \"Net Total\" -%}\n					<tr class=\"row-divider\">\n						<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">\n							{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n						</td>\n						<td class=\"text-right\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n					</tr>\n				{%- endif -%}\n				{%- for tax in doc.taxes -%}\n					{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}\n						<tr class=\"row-divider\">\n							<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">{{ tax.get_formatted(\"description\") }} ({{ tax.get_formatted(\"rate\") }}%):</td>\n							<td class=\"text-right\">{{ tax.get_formatted(\"tax_amount\") }}</td>\n						</tr>\n					{%- endif -%}\n				{%- endfor -%}\n				{%- if doc.apply_discount_on == \"Grand Total\" -%}\n					<tr class=\"row-divider\">\n						<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">\n							{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n						</td>\n						<td class=\"text-right\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n					</tr>\n				{%- endif -%}\n			</table>\n		</div>\n\n		<div style=\"border-bottom: 1px solid #ededed;\">\n			<table class=\"highlight-bg\" style=\"width: 100%; border-collapse: collapse; border-radius: 12px; margin-bottom: 10px;\">\n				<tr>\n					<td class=\"text-left mw-400\">\n						<div class=\"text-capitalize\">\n							<span class=\"title\"> {{ _(\"In Words: \") }}</span>{{ doc.in_words }}\n						</div>\n					</td>\n					<td class=\"text-right\"><b>{{ _(\"Grand Total:\") }}</b></td>\n					<td class=\"text-right\">\n						<span style=\"font-weight: 700\">\n							{{ doc.get_formatted(\"grand_total\", doc) }}\n						</span>\n					</td>\n				</tr>\n			</table>\n		</div>\n\n\n		<!-- Terms -->\n		{% if doc.terms %}\n		<div class=\"info-card\">\n			<div class=\"title\">{{ _(\"Terms and Conditions\") }}</div>\n			{{ doc.terms}}\n		</div>\n		{% endif %}\n	</div>\n	<div {% if print_settings.repeat_header_footer %} id=\"footer-html\" class=\"visible-pdf\" {% endif %}>\n		{% if not no_letterhead and footer %}\n		<div class=\"letter-head-footer\">\n			{{ footer }}\n		</div>\n		{% endif %}\n		{% if print_settings.repeat_header_footer %}\n		<p class=\"text-center small page-number visible-pdf\">\n			{{ _(\"Page {0} of {1}\").format(\'<span class=\"page\"></span>\', \'<span class=\"topage\"></span>\') }}\n		</p>\n		{% endif %}\n	</div>\n</div>\n{% endfor %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,NULL,NULL,'Hide',0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Detailed Tax Invoice','2017-12-07 16:26:06.648472','2024-10-02 14:53:28.661507','Administrator','Administrator',0,0,NULL,'Sales Invoice',NULL,'Regional',NULL,NULL,'Yes',0,1,NULL,'Jinja',0,NULL,NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Default',NULL,NULL,NULL,0,NULL,'[{\"fieldname\": \"print_heading_template\", \"fieldtype\": \"Custom HTML\", \"options\": \"<div class=\\\"print-heading\\\">\\t\\t\\t\\t<h2>TAX Invoice<br><small>{{ doc.name }}</small>\\t\\t\\t\\t</h2></div>\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"customer_name\", \"label\": \"Customer Name\"}, {\"print_hide\": 0, \"fieldname\": \"customer_name_in_arabic\", \"label\": \"Customer Name in Arabic\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"posting_date\", \"label\": \"Date\"}, {\"print_hide\": 0, \"fieldname\": \"project\", \"align\": \"left\", \"label\": \"Reverse Charge Applicable\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Address\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"address_display\", \"label\": \"Address\"}, {\"print_hide\": 0, \"fieldname\": \"tax_id\", \"label\": \"Tax Id\"}, {\"print_hide\": 0, \"fieldname\": \"contact_display\", \"label\": \"Contact\"}, {\"print_hide\": 0, \"fieldname\": \"contact_mobile\", \"label\": \"Mobile No\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"company\", \"label\": \"Company\"}, {\"print_hide\": 0, \"fieldname\": \"company_address_display\", \"label\": \"Company Address\"}, {\"print_hide\": 0, \"fieldname\": \"company_trn\", \"label\": \"Company TRN\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"visible_columns\": [{\"print_hide\": 0, \"fieldname\": \"item_code\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"description\", \"print_width\": \"200px\"}, {\"print_hide\": 0, \"fieldname\": \"image\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"qty\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"uom\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"rate\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"amount\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"tax_code\", \"print_width\": \"\"}], \"print_hide\": 0, \"fieldname\": \"items\", \"label\": \"Items\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"total\", \"label\": \"Total\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"visible_columns\": [{\"print_hide\": 0, \"fieldname\": \"charge_type\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"row_id\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"account_head\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"cost_center\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"description\", \"print_width\": \"300px\"}, {\"print_hide\": 0, \"fieldname\": \"rate\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"tax_amount\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"total\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"tax_amount_after_discount_amount\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"base_tax_amount\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"base_total\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"base_tax_amount_after_discount_amount\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"item_wise_tax_detail\", \"print_width\": \"\"}], \"print_hide\": 0, \"fieldname\": \"taxes\", \"label\": \"Sales Taxes and Charges\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"grand_total\", \"label\": \"Grand Total\"}, {\"print_hide\": 0, \"fieldname\": \"rounded_total\", \"label\": \"Rounded Total\"}, {\"print_hide\": 0, \"fieldname\": \"in_words\", \"align\": \"left\", \"label\": \"In Words\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"other_charges_calculation\", \"label\": \"Taxes and Charges Calculation\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Terms\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"terms\", \"nolabel\": 1, \"label\": \"Terms and Conditions Details\"}]',NULL,NULL,1,0,NULL,NULL,NULL,NULL),
('Drop Shipping Format','2015-12-04 13:11:16.992997','2016-03-07 20:49:39.443328','Administrator','Administrator',0,0,NULL,'Purchase Order',NULL,NULL,NULL,NULL,'Yes',1,0,NULL,'Jinja',0,'<div class=\"page-break\">\n    <div class=\"print-heading\">\n		<h2>Purchase Order<br>\n	        <small>{{doc.name}}</small>\n        </h2>\n    </div>\n    <div class=\"row section-break\">\n        <div class=\"col-xs-6 column-break\">\n                <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Supplier Name</label>\n					</div>\n					<div class=\"col-xs-7  value\">\n						{{doc.supplier_name}}\n					</div>\n				</div>\n				{% if doc.address_display %}\n	                <div class=\"row\">\n						<div class=\"col-xs-5 text-right\">\n							<label>Address</label>\n						</div>\n						<div class=\"col-xs-7  value\">\n							{{doc.address_display}}\n						</div>\n					</div>\n				{%- endif -%}\n				{% if doc.contact_display %}\n	                <div class=\"row\">\n						<div class=\"col-xs-5 text-right\">\n							<label>Contact</label>\n						</div>\n						<div class=\"col-xs-7  value\">\n							{{doc.contact_display}}\n						</div>\n					</div>\n				{%- endif -%}\n				{% if doc.contact_mobile %}\n	                <div class=\"row\">\n						<div class=\"col-xs-5 text-right\">\n							<label>Mobile No</label>\n						</div>\n						<div class=\"col-xs-7  value\">\n							{{doc.contact_mobile}}\n						</div>\n					</div>\n				{%- endif -%}\n        </div>\n        \n        <div class=\"col-xs-6 column-break\">\n            <div class=\"row\">\n				<div class=\"col-xs-5 text-right\">\n					<label>Date</label>\n				</div>\n				<div class=\"col-xs-7  value\">\n					{{doc.transaction_date}}\n				</div>\n			</div>\n            <div class=\"row\">\n				<div class=\"col-xs-5 text-right\">\n					<label>Customer Name</label>\n				</div>\n				<div class=\"col-xs-7  value\">\n					{{doc.customer_name}}\n				</div>\n			</div>\n			{% if doc.shipping_address_display %}\n	            <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Customer Address</label>\n					</div>\n					<div class=\"col-xs-7  value\">\n						{{doc.shipping_address_display}}\n					</div>\n				</div>\n			{%- endif -%}\n			{% if doc.customer_contact_display %}\n	            <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Customer Contact</label>\n					</div>\n					<div class=\"col-xs-7  value\">\n						{{doc.customer_contact_display}}\n					</div>\n				</div>\n			{%- endif -%}\n			{% if doc.customer_contact_mobile %}\n	            <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Customer Mobile No</label>\n					</div>\n					<div class=\"col-xs-7  value\">\n						{{doc.customer_contact_mobile}}\n					</div>\n				</div>\n			{%- endif -%}\n        </div>\n    </div>\n	<table class=\"table table-bordered\">\n		<tbody>\n			<tr>\n				<th>Sr</th>\n				<th>Item Name</th>\n				<th>Description</th>\n				<th class=\"text-right\">Qty</th>\n				<th class=\"text-right\">Rate</th>\n				<th class=\"text-right\">Amount</th>\n			</tr>\n			{%- for row in doc.items -%}\n			<tr>\n				<td style=\"width: 3%;\">{{ row.idx }}</td>\n				<td style=\"width: 20%;\">\n					{{ row.item_name }}\n					{% if row.item_code != row.item_name -%}\n					<br>Item Code: {{ row.item_code}}\n					{%- endif %}\n				</td>\n				<td style=\"width: 37%;\">\n					<div style=\"border: 0px;\">{{ row.description }}</div></td>\n				<td style=\"width: 10%; text-align: right;\">{{ row.qty }} {{ row.uom or row.stock_uom }}</td>\n				<td style=\"width: 15%; text-align: right;\">{{\n					row.get_formatted(\"rate\", doc) }}</td>\n				<td style=\"width: 15%; text-align: right;\">{{\n					row.get_formatted(\"amount\", doc) }}</td>\n			</tr>\n			{%- endfor -%}\n		</tbody>\n	</table>\n    <div class=\"row section-break\">\n        <div class=\"col-xs-6 column-break\">\n        </div>\n        <div class=\"col-xs-6 column-break\">\n                <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Total</label>\n					</div>\n					<div class=\"col-xs-7 text-right value\">\n						{{doc.total}}\n					</div>\n				</div>\n                <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>Grand Total</label>\n					</div>\n					<div class=\"col-xs-7 text-right value\">\n						{{doc.grand_total}}\n					</div>\n				</div>\n                <div class=\"row\">\n					<div class=\"col-xs-5 text-right\">\n						<label>In Words</label>\n					</div>\n					<div class=\"col-xs-7 text-right value\">\n						{{doc.in_words}}\n					</div>\n				</div>\n        </div>\n    </div>\n</div>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Default',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Dunning Letter','2019-12-11 04:37:14.012805','2024-10-02 14:50:53.572939','Administrator','Administrator',0,0,NULL,'Dunning',NULL,'Accounts','en',NULL,'Yes',0,0,NULL,'Jinja',0,NULL,NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Arial',NULL,NULL,NULL,0,'.print-format th {\n    background-color: transparent !important;\n    border-bottom: 1px solid !important;\n    border-top: none !important;\n}\n.print-format .ql-editor {\n    padding-left: 0px;\n    padding-right: 0px;\n}\n\n.print-format table {\n    margin-bottom: 0px;\n    }\n.print-format .table-data tr:last-child { \n    border-bottom: 1px solid !important;\n}\n\n.print-format .table-inner tr:last-child {\n    border-bottom:none !important;\n}\n.print-format .table-inner {\n    margin: 0px 0px;\n}\n\n.print-format .table-data ul li { \n    color:#787878 !important;\n}\n\n.no-top-border {\n    border-top:none !important;\n}\n\n.table-inner td {\n    padding-left: 0px !important;    \n    padding-top: 1px !important;\n    padding-bottom: 1px !important;\n    color:#787878 !important;\n}\n\n.total {\n    background-color: lightgrey !important;\n    padding-top: 4px !important;\n    padding-bottom: 4px !important;\n}\n','[{\"fieldname\": \"print_heading_template\", \"fieldtype\": \"Custom HTML\", \"options\": \"<div></div>\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"_custom_html\", \"print_hide\": 0, \"label\": \"Custom HTML\", \"fieldtype\": \"HTML\", \"options\": \"<b>{{doc.customer_name}}</b> <br />\\n{{doc.address_display}}\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"_custom_html\", \"print_hide\": 0, \"label\": \"Custom HTML\", \"fieldtype\": \"HTML\", \"options\": \"<div style=\\\"text-align:left;\\\">\\n<div style=\\\"font-size:24px; text-transform:uppercase;\\\">{{_(doc.dunning_type)}}</div>\\n<div style=\\\"font-size:16px;padding-bottom:5px;\\\">{{ doc.name }}</div>\\n</div>\"}, {\"fieldname\": \"posting_date\", \"print_hide\": 0, \"label\": \"Date\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"body_text\", \"nolabel\": 1, \"print_hide\": 0, \"label\": \"Body Text\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"overdue_payments\", \"print_hide\": 0, \"label\": \"Overdue Payments\", \"visible_columns\": [{\"fieldname\": \"sales_invoice\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"dunning_level\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"due_date\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"overdue_days\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"invoice_portion\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"outstanding\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"interest\", \"print_width\": \"\", \"print_hide\": 0}]}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"total_outstanding\", \"print_hide\": 0, \"label\": \"Total Outstanding\"}, {\"fieldname\": \"dunning_fee\", \"print_hide\": 0, \"label\": \"Dunning Fee\"}, {\"fieldname\": \"total_interest\", \"print_hide\": 0, \"label\": \"Total Interest\"}, {\"fieldname\": \"grand_total\", \"print_hide\": 0, \"label\": \"Grand Total\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"closing_text\", \"nolabel\": 1, \"print_hide\": 0, \"label\": \"Closing Text\"}]',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('General Ledger Standard','2026-03-25 00:31:49.971580','2026-05-20 20:05:27.699070','Administrator','Administrator',0,0,'Report',NULL,'General Ledger','Accounts','en',NULL,'Yes',1,0,'chrome','JS',0,'<style type=\"text/css\">\n    body, html {\n        margin-top: 10px;\n        padding: 0;\n        width: 100%;\n        height: auto;\n        font-family: Inter, sans-serif;\n        font-size: 14px;\n        line-height: 21px;\n        color: #171717;\n    }\n\n    .title-letter-spacing {\n		font-size: 14px;\n		font-weight: 600;\n		color: #171717;\n    }\n\n    .report-table table {\n        width: 100%;\n        table-layout: fixed;\n        border-collapse: separate;\n        border-spacing: 0;\n    }\n\n    .report-table thead th {\n        background: #f8f8f8;\n        text-align: center;\n		font-size: 14px;\n        font-weight: 420;\n        color: #7c7c7c;\n        border-top: 1px solid #ededed;\n        border-bottom: 1px solid #ededed;\n        padding: 6px 8px;\n    }\n\n    .report-table tbody td {\n        padding: 6px 8px;\n        border-bottom: 1px solid #ededed;\n        vertical-align: top;\n        word-wrap: break-word;\n        font-size: 14px;\n    }\n\n    .report-table thead tr:first-child th:first-child {\n        border-left: 1px solid #ededed;\n        border-top-left-radius: 10px;\n        border-bottom-left-radius: 10px;\n    }\n    \n    .report-table thead tr:first-child th:last-child {\n        border-right: 1px solid #ededed;\n        border-top-right-radius: 10px;\n        border-bottom-right-radius: 10px;\n    }\n\n    .report-table tbody tr:last-child td {\n        border-bottom: none;\n    }\n\n    .date-col {\n        white-space: nowrap;\n    }\n\n    .text-center { text-align: center; }\n    .text-left { text-align: left; }\n    .text-right { text-align: right; font-variant-numeric: tabular-nums; }\n    .text-muted { color: #7c7c7c; }\n\n    .text-bold { font-weight: 700; }\n\n    .report-meta {\n        margin: 10px 0 14px;\n        padding: 8px 10px;\n        color: #171717;\n		font-size: 14px;\n        display: flex;\n        justify-content: space-between;\n        align-items: flex-start;\n        gap: 12px;\n    }\n\n    .report-meta .left,\n    .report-meta .right {\n        display: flex;\n        flex-direction: column;\n    }\n\n    .report-meta .filter-row {\n        margin-bottom: 4px;\n        line-height: 1.5;\n    }\n\n    .report-meta strong {\n        color: #7c7c7c;\n        font-weight: 500;\n    }\n\n    @media print {\n        @page {\n            size: A4;\n            margin-top: 10mm;\n        }\n        thead {\n            display: table-header-group;\n        }\n        tfoot {\n            display: table-footer-group;\n        }\n        tr {\n            page-break-inside: avoid;\n        }\n        .no-print {\n            display: none !important;\n        }\n    }\n</style>\n\n<br>\n\n<div>\n\n    <div class=\"text-center\" style=\"margin-bottom: 12px;\">\n        <div class=\"title-letter-spacing\">\n            {%= __(\"Statement Of Accounts\") %}\n        </div>\n    </div>\n\n    {% if (subtitle && subtitle.trim()) { %}\n        <div class=\"report-meta\">\n            {{ subtitle }}\n        </div>\n    {% } else { %}\n       <div class=\"report-meta\">\n			<div class=\"left\">\n				<div class=\"filter-row\">\n					<strong>{%= __(\"Customer\") %}:</strong>\n					{%=\n						(filters.party.length && filters.party.join(\", \")) || filters.party_name || \"All Parties\"\n					%}\n				</div>\n			</div>\n\n			<div class=\"right text-right\">\n				<div class=\"filter-row\">\n					<strong>{%= __(\"Statement Period\") %}:</strong>\n					{%= __(\"{0} to {1}\", [\n						frappe.datetime.str_to_user(filters.from_date),\n						frappe.datetime.str_to_user(filters.to_date)\n					]) %}\n				</div>\n			</div>\n		</div>\n    {% } %}\n\n    <div class=\"report-table\">\n        <table>\n            <thead>\n                <tr>\n                    <th style=\"width: 8em; text-align: left;\">{%= __(\"Date\") %}</th>\n                    <th style=\"text-align: left;\">{%= __(\"Voucher Details\") %}</th>\n\n                    {% if(filters.show_remarks) { %}\n                        <th>{%= __(\"Remarks\") %}</th>\n                    {% } %}\n\n                    <th style=\"width: 10em; text-align: right;\">{%= __(\"Debit\") %}</th>\n                    <th style=\"width: 10em; text-align: right;\">{%= __(\"Credit\") %}</th>\n                    <th style=\"width: 10em; text-align: right;\">{%= __(\"Balance\") %}</th>\n                </tr>\n            </thead>\n\n            <tbody>\n				{% for(var i=0, l=data.length; i<l; i++) { %}\n					{% var row = data[i]; %}\n					{% var is_entry = row.posting_date; %}\n					{% var is_last = i == l-1; %}\n					{% var is_second_last = i == l-2; %}\n\n					<tr>\n\n						<!-- Date -->\n						<td class=\"text-left date-col\">\n							{% if(is_entry) { %}\n								{%= frappe.datetime.str_to_user(row.posting_date) %}\n							{% } else if(i == 0) { %}\n								{%= frappe.datetime.str_to_user(filters.from_date) %}\n							{% } %}\n						</td>\n\n						<!-- Voucher Details -->\n						<td class=\"{% if(!is_entry) { %}text-left text-bold{% } %}\">\n							{% if(is_entry) { %}\n\n								{%= row.voucher_type %} {%= row.voucher_no %}\n\n								{% if(!(filters.party || filters.account)) { %}\n									<div style=\"margin-top: 2px;\">\n										{%= row.party || row.account %}\n									</div>\n								{% } %}\n\n								{% if(row.bill_no) { %}\n									<div style=\"margin-top: 2px;\">\n										{%= __(\"Supplier Invoice No\") %}: {%= row.bill_no %}\n									</div>\n								{% } %}\n\n							{% } else { %}\n\n								{% if(is_second_last) { %}\n									{%= __(\"Total\") %}\n								{% } else if(is_last) { %}\n									{%= __(\"Closing [Opening + Total] \") %}\n								{% } else { %}\n									{%= frappe.format(row.account, {fieldtype: \"Link\"}) || \"&nbsp;\" %}\n								{% } %}\n\n							{% } %}\n						</td>\n\n						<!-- Remarks -->\n						{% if(filters.show_remarks) { %}\n						<td class=\"text-left\">\n							{% if(is_entry && row.remarks && row.remarks != \"No Remarks\") { %}\n								{%= row.remarks %}\n							{% } %}\n						</td>\n						{% } %}\n\n						<!-- Debit -->\n						<td class=\"text-right\">\n							{% if(is_entry) { %}\n								{% if(row.debit != 0) { %}\n									{%= format_currency(row.debit, filters.presentation_currency) %}\n								{% } %}\n							{% } else if(i != 0 && !is_last) { %}\n								{%= row.account && format_currency(row.debit, filters.presentation_currency) %}\n							{% } %}\n						</td>\n\n						<!-- Credit -->\n						<td class=\"text-right\">\n							{% if(is_entry) { %}\n								{% if(row.credit != 0) { %}\n									{%= format_currency(row.credit, filters.presentation_currency) %}\n								{% } %}\n							{% } else if(i != 0 && !is_last) { %}\n								{%= row.account && format_currency(row.credit, filters.presentation_currency) %}\n							{% } %}\n						</td>\n\n						<!-- Balance -->\n						<td class=\"text-right {% if(is_last) { %}text-bold{% } %}\">\n							{% if(is_last) { %}\n								{%= format_currency(row.balance, filters.presentation_currency) %}\n								{% if(row.balance < 0) { %} Cr{% } %}\n								{% if(row.balance > 0) { %} Dr{% } %}\n							{% } else { %}\n								{%= format_currency(row.balance, filters.presentation_currency) %}\n							{% } %}\n						</td>\n\n					</tr>\n				{% } %}\n			</tbody>\n        </table>\n    </div>\n\n    <p class=\"text-right text-muted\">\n        {%= __(\"Printed on {0}\", [\n            frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n        ]) %}\n    </p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,NULL,NULL,'Hide',0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
