('Pick List','2019-08-02 07:27:42.533305','2019-08-30 15:58:27.807219','Administrator','Administrator',0,0,NULL,'Pick List',NULL,'Stock',NULL,NULL,'Yes',0,0,NULL,'Jinja',0,NULL,NULL,0.000000000,0.000000000,0.000000000,0.000000000,1,1,1,0,0,'Default',NULL,NULL,NULL,0,NULL,'[{\"fieldname\": \"print_heading_template\", \"fieldtype\": \"Custom HTML\", \"options\": \"<div class=\\\"print-heading\\\">\\t\\t\\t\\t<h2>Pick List<br><small>{{ doc.name }}</small>\\t\\t\\t\\t</h2></div>\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"company\", \"label\": \"Company\"}, {\"print_hide\": 0, \"fieldname\": \"customer\", \"label\": \"Customer\"}, {\"fieldtype\": \"Column Break\"}, {\"print_hide\": 0, \"fieldname\": \"purpose\", \"label\": \"Purpose\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"visible_columns\": [{\"print_hide\": 0, \"fieldname\": \"item_name\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"warehouse\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"qty\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"stock_qty\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"serial_no\", \"print_width\": \"\"}, {\"print_hide\": 0, \"fieldname\": \"batch_no\", \"print_width\": \"\"}], \"print_hide\": 0, \"fieldname\": \"locations\", \"label\": \"Item Locations\"}]',NULL,NULL,1,0,NULL,NULL,NULL,NULL),
('POS Invoice','2011-12-21 11:08:55.000000','2021-04-15 15:23:28.867135','Administrator','Administrator',0,1,NULL,'POS Invoice',NULL,'Selling',NULL,NULL,'Yes',1,0,NULL,'Jinja',0,'<style>\n	.print-format table, .print-format tr, \n	.print-format td, .print-format div, .print-format p {\n		line-height: 150%;\n		vertical-align: middle;\n	}\n	@media screen {\n		.print-format {\n			width: 4in;\n			padding: 0.25in;\n			min-height: 8in;\n		}\n	}\n</style>\n\n{% if letter_head %}\n    {{ letter_head }}\n{% endif %}\n\n<p class=\"text-center\" style=\"margin-bottom: 1rem\">\n	{{ doc.company }}<br>\n	<b>{{ doc.select_print_heading or _(\"Invoice\") }}</b><br>\n</p>\n<p>\n	<b>{{ _(\"Receipt No\") }}:</b> {{ doc.name }}<br>\n	<b>{{ _(\"Cashier\") }}:</b> {{ doc.owner }}<br>\n	<b>{{ _(\"Customer\") }}:</b> {{ doc.customer_name }}<br>\n	<b>{{ _(\"Date\") }}:</b> {{ doc.get_formatted(\"posting_date\") }}<br>\n	<b>{{ _(\"Time\") }}:</b> {{  doc.get_formatted(\"posting_time\") }}<br>\n</p>\n\n<hr>\n<table class=\"table table-condensed\">\n	<thead>\n		<tr>\n			<th width=\"50%\">{{ _(\"Item\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Qty\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Amount\") }}</th>\n		</tr>\n	</thead>\n	<tbody>\n		{%- for item in doc.items -%}\n		<tr>\n			<td>\n				{{ item.item_code }}\n				{%- if item.item_name != item.item_code -%}\n					<br>{{ item.item_name }}\n				{%- endif -%}\n				{%- if item.serial_no -%}\n					<br><b>{{ _(\"SR.No\") }}:</b><br>\n					{{ item.serial_no | replace(\"\\n\", \", \") }}\n				{%- endif -%}\n			</td>\n			<td class=\"text-right\">{{ item.qty }}<br>@ {{ item.get_formatted(\"rate\") }}</td>\n			<td class=\"text-right\">{{ item.get_formatted(\"amount\") }}</td>\n		</tr>\n		{%- endfor -%}\n	</tbody>\n</table>\n<table class=\"table table-condensed no-border\">\n	<tbody>\n		<tr>\n			{% if doc.flags.show_inclusive_tax_in_print %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total Excl. Tax\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"net_total\", doc) }}\n				</td>\n			{% else %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"total\", doc) }}\n				</td>\n			{% endif %}\n		</tr>\n		{%- for row in doc.taxes -%}\n		  {%- if not row.included_in_print_rate or doc.flags.show_inclusive_tax_in_print -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {% if \'%\' in row.description %}\n					    {{ row.description }}\n					{% else %}\n					    {{ row.description }}@{{ row.rate }}%\n					{% endif %}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"tax_amount\", doc) }}\n				</td>\n			<tr>\n		  {%- endif -%}\n		{%- endfor -%}\n\n		{%- if doc.discount_amount -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				{{ _(\"Discount\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"discount_amount\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Grand Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"grand_total\") }}\n			</td>\n		</tr>\n		{%- if doc.rounded_total -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Rounded Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"rounded_total\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		{%- for row in doc.payments -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {{ row.mode_of_payment }}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"amount\", doc) }}\n				</td>\n			<tr>\n		{%- endfor -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Paid Amount\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"paid_amount\") }}\n			</td>\n		</tr>\n		{%- if doc.change_amount -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 75%\">\n					<b>{{ _(\"Change Amount\") }}</b>\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"change_amount\") }}\n				</td>\n			</tr>\n		{%- endif -%}\n	</tbody>\n</table>\n<hr>\n<p>{{ doc.terms or \"\" }}</p>\n<p class=\"text-center\">{{ _(\"Thank you, please visit again.\") }}</p>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
