('Request for Quotation with Item Image','2026-03-19 15:17:39.094444','2026-07-03 02:26:31.243291','Administrator','Administrator',0,0,'DocType','Request for Quotation',NULL,'Buying','en',NULL,'Yes',1,0,'wkhtmltopdf','Jinja',0,'{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}\n\n{% if letter_head and not no_letterhead %}\n<div class=\"letter-head\">{{ letter_head }}</div>\n{% endif %}\n{% if print_heading_template %}\n{{ frappe.render_template(print_heading_template, {\"doc\":doc}) }}\n{% endif %}\n{%- endmacro -%}\n\n{% for page in layout %}\n<div class=\"page-break invoice-page\">\n	<div {% if print_settings.repeat_header_footer %} id=\"header-html\" class=\"hidden-pdf\" {% endif %}>\n		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}\n	</div>\n	{%- if doc.meta.is_submittable and doc.docstatus==2-%}\n		<div class=\"text-center\" document-status=\"cancelled\">\n			<h4 style=\"margin-top: 20px;\">{{ _(\"CANCELLED\") }}</h4>\n		</div>\n	{%- endif -%}\n	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}\n		<div class=\"text-center\" document-status=\"draft\">\n			<h4 style=\"margin-top: 20px !important;\">{{ _(\"DRAFT\") }}</h4>\n		</div>\n	{%- endif -%}\n\n	<style>\n		.letter-head {\n			padding-top: 12px !important;\n			padding-bottom: 12px !important;\n		}\n		.invoice-page {\n			font-family: Inter, sans-serif;\n			color: #171717;\n		}\n\n		.print-format-body {\n			padding: 30px 12px 12px 12px !important;\n		}\n\n		.title {\n			color: #7c7c7c !important;\n		}\n		.text-muted {\n			color: #7c7c7c !important;\n		}\n		.text-dark {\n			color: #171717 !important;\n		}\n		.small-text {\n			font-size: 11px;\n			color: #666;\n		}\n\n		.text-left {\n			text-align: left;\n		}\n		.text-center {\n			text-align: center;\n		}\n		.text-right {\n			text-align: right;\n		}\n		.text-bold {\n			font-weight: 700;\n		}\n\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-16 {\n			margin-top: 16px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mw-400 {\n			max-width: 400px;\n		}\n\n		.items-table,\n		.tax-table {\n			width: 100%;\n			border-collapse: separate;\n			border-spacing: 0;\n			border-radius: 10px;\n			overflow: hidden;\n		}\n\n		.items-table td,\n		.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		.items-table thead td,\n		.tax-table thead td {\n			color: #7c7c7c !important;\n		}\n		.items-table thead tr:first-of-type td,\n		.tax-table thead tr:first-of-type td {\n			border-bottom: none;\n		}\n\n		.items-table thead tr:first-child td:first-child,\n		.tax-table thead tr:first-child td:first-child {\n			border-top-left-radius: 10px;\n			border-bottom-left-radius: 10px;\n		}\n		.items-table thead tr:first-child td:last-child,\n		.tax-table thead tr:first-child td:last-child {\n			border-top-right-radius: 10px;\n			border-bottom-right-radius: 10px;\n		}\n\n		.in-words {\n			color: #171717 !important;\n			max-width: 400px;\n			word-wrap: break-word;\n			line-height: 1.5;\n			font-size: 12px;\n		}\n\n		.row-divider {\n			border-bottom: 1px solid #e9e9e9;\n		}\n\n		.highlight-bg {\n			background: #f8f8f8;\n		}\n\n		.info-card {\n			margin-top: 40px;\n			color: #7c7c7c;\n		}\n\n		.info-text {\n			margin-bottom: 12px;\n		}\n\n		.print-format {\n			color: #171717;\n			font-size: 14px;\n			font-style: normal;\n			font-weight: 420;\n			line-height: 21px;\n			padding: 0px !important;\n			margin-left: 0mm !important;\n			margin-right: 0mm !important;\n		}\n\n		.letter-head-footer {\n			margin-top: 0px !important;\n		}\n\n		.print-format-body td {\n			padding: 8px 8px !important;\n		}\n\n		.tax-table td,\n		.items-table td {\n			height: auto !important;\n		}\n\n		.tax-table thead td,\n		.items-table thead td {\n			height: 32px;\n		}\n\n		.item-img td {\n			border: none !important;\n			padding: 0px !important;\n		}\n	</style>\n\n	<div class=\"print-format-body\">\n		<table class=\"info-table col-xs-12\" style=\"width: 100%; margin-left: 12px\">\n			<tr>\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Supplier Name:\") }}</div>\n						<div class=\"info-text\">{{ _(\"Shipping Address:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.vendor }}</div>\n						<div class=\"info-text\">\n        					{% if doc.shipping_address %}\n        						{% set shipping_address = frappe.db.get_value(\"Address\", doc.shipping_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n                                {{ doc.shipping_address }}<br>\n        						{{ shipping_address.address_line1 or \"\" }}<br>\n        						{% if shipping_address.address_line2 %}{{ shipping_address.address_line2 }}<br>{% endif %}\n        						{{ shipping_address.city or \"\" }} {{ shipping_address.state or \"\" }} {{ shipping_address.pincode or \"\" }} {{ shipping_address.country or \"\" }}<br>\n        					{% endif %}\n						</div>\n\n					</div>\n				</td>\n\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Order Date:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ frappe.utils.format_date(doc.transaction_date) }}</div>\n					</div>\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Required By:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ frappe.utils.format_date(doc.schedule_date) }}</div>\n					</div>\n				</td>\n			</tr>\n		</table>\n\n		<!-- Items Table -->\n		{% set item_naming_by = frappe.db.get_single_value(\"Stock Settings\", \"item_naming_by\") %}\n		<table class=\"items-table mt-15\">\n			<thead class=\"highlight-bg\">\n				<tr>\n					<td class=\"	text-center\">{{ _(\"No\") }}</td>\n					<td class=\"text-left\">{{ _(\"Item\") }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ _(\"Item Code\") }}</td>\n					{% endif %}\n					<td class=\"text-right\">{{ _(\"Quantity\") }}</td>\n				</tr>\n			</thead>\n			<tbody>\n				{% for item in doc.items %}\n				<tr>\n					<td class=\"text-center\">{{ loop.index }}</td>\n					<td class=\"text-left\">\n						<table class=\"item-img\" style=\"border-collapse: collapse\">\n							<tr>\n								{% if item.image %}\n								<td class=\"no-style\" style=\"border-radius: 6px; vertical-align: middle\">\n									<img\n										src=\"{{ item.image | e }}\"\n										alt=\"{{ item.item_name | e }}\"\n										style=\"\n											border-radius: 6px;\n											height: 24px;\n											width: 24px !important;\n											margin-right: 8px;\n                                            vertical-align: middle;\n										\"\n									/>\n								</td>\n								{% endif %}\n								<td\n									class=\"no-style\"\n									style=\"vertical-align: middle !important; padding: 0 !important\"\n								>\n									{{ item.item_name }}\n								</td>\n							</tr>\n						</table>\n					</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ item.item_code }}</td>\n					{% endif %}\n\n					<td class=\"text-right\">{{ item.get_formatted(\"qty\", 0) }} {{ item.uom }}</td>\n				</tr>\n				{% endfor %}\n			</tbody>\n		</table>\n\n\n		<!-- Terms -->\n		{% if doc.terms %}\n		<div class=\"info-card\">\n			<div class=\"title\">{{ _(\"Terms and Conditions\") }}</div>\n			{{ doc.terms}}\n		</div>\n		{% endif %}\n	</div>\n	<div {% if print_settings.repeat_header_footer %} id=\"footer-html\" class=\"visible-pdf\" {% endif %}>\n		{% if not no_letterhead and footer %}\n		<div class=\"letter-head-footer\">\n			{{ footer }}\n		</div>\n		{% endif %}\n		{% if print_settings.repeat_header_footer %}\n		<p class=\"text-center small page-number visible-pdf\">\n			{{ _(\"Page {0} of {1}\").format(\'<span class=\"page\"></span>\', \'<span class=\"topage\"></span>\') }}\n		</p>\n		{% endif %}\n	</div>\n</div>\n{% endfor %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,NULL,NULL,'Hide',0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Return POS Invoice','2020-05-14 17:02:44.207166','2020-05-14 17:13:29.354015','Administrator','Administrator',0,0,NULL,'POS Invoice',NULL,'Selling','en',NULL,'Yes',1,0,NULL,'Jinja',0,'<style>\n	.print-format table, .print-format tr, \n	.print-format td, .print-format div, .print-format p {\n		font-family: Tahoma, sans-serif;\n		line-height: 150%;\n		vertical-align: middle;\n	}\n	@media screen {\n		.print-format {\n			width: 4in;\n			padding: 0.25in;\n			min-height: 8in;\n		}\n	}\n</style>\n\n{% if letter_head %}\n    {{ letter_head }}\n{% endif %}\n\n<p class=\"text-center\" style=\"margin-bottom: 1rem\">\n	{{ doc.company }}<br>\n	{{ doc.select_print_heading or _(\"Return Invoice\") }}<br>\n</p>\n<p>\n	<b>{{ _(\"Receipt No\") }}:</b> {{ doc.name }}<br>\n	<b>{{ _(\"Original Invoice\") }}:</b> {{ doc.return_against }}<br>\n	<b>{{ _(\"Date\") }}:</b> {{ doc.get_formatted(\"posting_date\") }}<br>\n	<b>{{ _(\"Customer\") }}:</b> {{ doc.customer_name }}\n</p>\n\n<hr>\n<table class=\"table table-condensed cart no-border\">\n	<thead>\n		<tr>\n			<th width=\"50%\">{{ _(\"Item\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Qty\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Amount\") }}</th>\n		</tr>\n	</thead>\n	<tbody>\n		{%- for item in doc.items -%}\n		<tr>\n			<td>\n				{{ item.item_code }}\n				{%- if item.item_name != item.item_code -%}\n					<br>{{ item.item_name }}\n				{%- endif -%}\n				{%- if item.serial_no -%}\n					<br><b>{{ _(\"SR.No\") }}:</b><br>\n					{{ item.serial_no | replace(\"\\n\", \", \") }}\n				{%- endif -%}\n			</td>\n			<td class=\"text-right\">{{ item.qty }}<br>@ {{ item.get_formatted(\"rate\") }}</td>\n			<td class=\"text-right\">{{ item.get_formatted(\"amount\") }}</td>\n		</tr>\n		{%- endfor -%}\n	</tbody>\n</table>\n<table class=\"table table-condensed no-border\">\n	<tbody>\n		<tr>\n			{% if doc.flags.show_inclusive_tax_in_print %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total Excl. Tax\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"net_total\", doc) }}\n				</td>\n			{% else %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"total\", doc) }}\n				</td>\n			{% endif %}\n		</tr>\n		{%- for row in doc.taxes -%}\n		  {%- if not row.included_in_print_rate or doc.flags.show_inclusive_tax_in_print -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {% if \'%\' in row.description %}\n					    {{ row.description }}\n					{% else %}\n					    {{ row.description }}@{{ row.rate }}%\n					{% endif %}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"tax_amount\", doc)}}\n				</td>\n			<tr>\n		  {%- endif -%}\n		{%- endfor -%}\n\n		{%- if doc.discount_amount -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				{{ _(\"Discount\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"discount_amount\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Grand Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"grand_total\") }}\n			</td>\n		</tr>\n		{%- if doc.rounded_total -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Rounded Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"rounded_total\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Paid Amount\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"paid_amount\") }}\n			</td>\n		</tr>\n		{%- if doc.change_amount -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 75%\">\n					<b>{{ _(\"Change Amount\") }}</b>\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"change_amount\")}}\n				</td>\n			</tr>\n		{%- endif -%}\n	</tbody>\n</table>\n<hr>\n<p>{{ doc.terms or \"\" }}</p>\n<p class=\"text-center\">{{ _(\"Thank you, please visit again.\") }}</p>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Default',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
