('Trial Balance Standard','2026-03-31 01:22:21.137577','2026-05-21 19:14:43.041737','Administrator','Administrator',0,0,'Report',NULL,'Trial Balance','Accounts','en',NULL,'Yes',1,0,'chrome','JS',0,'{%\n	const report_columns = report\n		.get_columns_for_print()\n		.filter(col => !col.hidden);\n\n	if (report_columns.length > 8) {\n		frappe.throw(\n			__(\"Too many columns. Export the report and print it using a spreadsheet application.\")\n		);\n	}\n%}\n\n<style>\n	body, html {\n		margin-top: 10px;\n		padding: 0;\n		width: 100%;\n		height: auto;\n		font-family: Inter, sans-serif;\n		font-size: 14px;\n		line-height: 21px;\n		color: #171717;\n	}\n\n	.title-letter-spacing {\n		font-size: 14px;\n		font-weight: 600;\n		color: #171717;\n	}\n\n	.financial-statements-important td {\n		font-weight: bold;\n	}\n\n	.financial-statements-blank-row td {\n		height: 43px;\n	}\n\n	.report-meta {\n		margin: 10px 0 14px;\n		padding: 8px 10px;\n		display: flex;\n		justify-content: space-between;\n		align-items: flex-start;\n		gap: 12px;\n		font-size: 14px;\n		color: #171717;\n	}\n\n	.report-meta .left,\n	.report-meta .right {\n		display: flex;\n		flex-direction: column;\n	}\n\n	.report-meta strong {\n		color: #7c7c7c;\n		font-weight: 500;\n	}\n\n	.report-subtitle {\n		margin: 10px 0 14px;\n	}\n\n	.text-center {\n		text-align: center;\n	}\n\n	.text-right {\n		text-align: right;\n		font-variant-numeric: tabular-nums;\n		white-space: nowrap;\n		overflow: hidden;\n		text-overflow: ellipsis;\n	}\n\n	.text-left {\n		text-align: left;\n	}\n\n	.text-bold {\n		font-weight: 700;\n	}\n\n	.text-muted {\n		color: #7c7c7c;\n	}\n\n	.report-table table {\n		width: 100%;\n		table-layout: fixed;\n		border-collapse: separate;\n		border-spacing: 0;\n	}\n\n	.report-table th,\n	.report-table td {\n		padding: 6px 8px;\n		font-size: 14px;\n		border-bottom: 1px solid #ededed;\n	}\n\n	.report-table thead th {\n		background: #f8f8f8;\n		font-weight: 500;\n		color: #7c7c7c;\n		border-top: 1px solid #ededed;\n		border-bottom: 1px solid #ededed;\n	}\n\n	.report-table tbody td.text-left {\n		vertical-align: top;\n		word-wrap: break-word;\n	}\n\n	.report-table thead tr:first-child th:first-child {\n		border-left: 1px solid #ededed;\n		border-top-left-radius: 10px;\n		border-bottom-left-radius: 10px;\n	}\n\n	.report-table thead tr:first-child th:last-child {\n		border-right: 1px solid #ededed;\n		border-top-right-radius: 10px;\n		border-bottom-right-radius: 10px;\n	}\n\n	.report-table tbody tr:last-child td {\n		border-bottom: none;\n	}\n\n	.report-table tbody tr {\n		height: 43px;\n	}\n\n	@media print {\n		@page {\n			size: A4;\n			margin-top: 10mm;\n		}\n\n		thead {\n			display: table-header-group;\n		}\n\n		tr {\n			page-break-inside: avoid;\n		}\n	}\n</style>\n\n<div>\n\n	<div class=\"text-center\" style=\"margin-bottom: 12px;\">\n		<div class=\"title-letter-spacing\">\n			{%= __(report.report_name) %}\n		</div>\n	</div>\n\n    {% if (subtitle && subtitle.trim()) { %}\n        <div class=\"report-subtitle\">\n            {{ subtitle }}\n        </div>\n    {% } else { %}\n        <div class=\"report-meta\">\n            <div class=\"left\">\n                <div>\n                    <strong>{%= __(\"Company\") %}:</strong> {%= filters.company %}\n                </div>\n                <div>\n                    <strong>{%= __(\"Currency\") %}:</strong>\n                    {%= filters.presentation_currency || erpnext.get_currency(filters.company) %}\n                </div>\n            </div>\n\n            <div class=\"right text-right\">\n                <div>\n                    <strong>{%= __(\"From Date\") %}:</strong>\n                    {%= frappe.datetime.str_to_user(filters.from_date) %}\n                </div>\n                <div>\n                    <strong>{%= __(\"To Date\") %}:</strong>\n                    {%= frappe.datetime.str_to_user(filters.to_date) %}\n                </div>\n            </div>\n        </div>\n    {% } %}\n\n	<div class=\"report-table\">\n    	<table>\n    		<thead>\n    			<tr>\n    				{% for (let i = 0, l = report_columns.length; i < l; i++) { %}\n    					{%\n    						const col = report_columns[i];\n    						const align = i === 0 ? \"text-left\" : \"text-right\";\n    						const styling = i === 0 ? \"\" : \"width: 9em\";\n    					%}\n    					<th class=\"{%= align %}\" style= \"{%= styling%}\">\n    						{%= col.label %}\n    					</th>\n    				{% } %}\n    			</tr>\n    		</thead>\n\n    		<tbody>\n    			{% for (let j = 0, k = data.length; j < k; j++) { %}\n    				{%\n    					const row = data[j];\n\n    					let row_class = \"\";\n    					if (!(row.parent_account || row.parent_section)) {\n    						row_class = \"financial-statements-important\";\n    					}\n    					if (!(row.account_name || row.section)) {\n    						row_class += \" financial-statements-blank-row\";\n    					}\n    				%}\n\n    				<tr class=\"{%= row_class %}\">\n    					{% for (let i = 0, l = report_columns.length; i < l; i++) { %}\n    						{%\n    							const col = report_columns[i];\n    							const value = row[col.fieldname];\n    							const align = i === 0 ? \"text-left\" : \"text-right\";\n    						%}\n\n    						<td class=\"{%= align %}\">\n    							{% if (i === 0) { %}\n    								<span style=\"padding-left: {%= cint(row.indent) * 2 %}em\">\n    									{%= String(row.account_name || row.section || \"\").replace(/^[\'\"]|[\'\"]$/g, \"\") %}\n    								</span>\n    							{% } else if (!is_null(value)) { %}\n    								{%= frappe.format(value, col, {}, row) %}\n    							{% } %}\n    						</td>\n    					{% } %}\n    				</tr>\n    			{% } %}\n    		</tbody>\n    	</table>\n    </div>\n\n	<p class=\"text-right text-muted\">\n		{%= __(\"Printed on {0}\", [\n			frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n		]) %}\n	</p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,NULL,NULL,'Hide',0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `tabPrint Format` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;

--
-- Table structure for table `tabPrint Format Field Template`
--

DROP TABLE IF EXISTS `tabPrint Format Field Template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `tabPrint Format Field Template` (
  `name` varchar(140) NOT NULL,
  `creation` datetime(6) DEFAULT NULL,
  `modified` datetime(6) DEFAULT NULL,
  `modified_by` varchar(140) DEFAULT NULL,
  `owner` varchar(140) DEFAULT NULL,
  `docstatus` tinyint(4) NOT NULL DEFAULT 0,
  `idx` int(11) NOT NULL DEFAULT 0,
  `document_type` varchar(140) DEFAULT NULL,
  `field` varchar(140) DEFAULT NULL,
  `standard` tinyint(4) NOT NULL DEFAULT 0,
  `module` varchar(140) DEFAULT NULL,
  `template_file` varchar(140) DEFAULT NULL,
  `template` longtext DEFAULT NULL,
  `_user_tags` text DEFAULT NULL,
  `_comments` text DEFAULT NULL,
  `_assign` text DEFAULT NULL,
  `_liked_by` text DEFAULT NULL,
  PRIMARY KEY (`name`),
