('Delivered Items To Be Billed','2013-07-30 17:28:49.000000','2017-11-06 13:04:36.338268','Administrator','Administrator',0,3,'Delivered Items To Be Billed','Sales Invoice',NULL,'Yes','Accounts',NULL,'Script Report',NULL,1,0,0,0,0,0,0,'select\n    `tabDelivery Note`.`name` as \"Delivery Note:Link/Delivery Note:120\",\n	`tabDelivery Note`.`customer` as \"Customer:Link/Customer:120\",\n	`tabDelivery Note`.`customer_name` as \"Customer Name::150\",\n	`tabDelivery Note`.`posting_date` as \"Date:Date\",\n	`tabDelivery Note`.`project` as \"Project\",\n	`tabDelivery Note Item`.`item_code` as \"Item:Link/Item:120\",\n	(`tabDelivery Note Item`.`base_amount` - `tabDelivery Note Item`.`billed_amt`*ifnull(`tabDelivery Note`.conversion_rate, 1)) as \"Pending Amount:Currency:110\",\n	`tabDelivery Note Item`.`item_name` as \"Item Name::150\",\n	`tabDelivery Note Item`.`description` as \"Description::200\",\n	`tabDelivery Note`.`company` as \"Company:Link/Company:\"\nfrom `tabDelivery Note`, `tabDelivery Note Item`\nwhere  \n    `tabDelivery Note`.name = `tabDelivery Note Item`.parent \n    and `tabDelivery Note`.docstatus = 1 \n    and `tabDelivery Note`.`status` not in (\"Stopped\", \"Closed\") \n    and `tabDelivery Note Item`.amount > 0\n    and `tabDelivery Note Item`.billed_amt < `tabDelivery Note Item`.amount\norder by `tabDelivery Note`.`name` desc',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
