('Received Items To Be Billed','2013-07-30 18:35:10.000000','2017-11-06 13:04:26.094432','Administrator','Administrator',0,3,'Received Items To Be Billed','Purchase Invoice',NULL,'Yes','Accounts',NULL,'Script Report',NULL,1,0,0,0,0,0,0,'select\n    `tabPurchase Receipt`.`name` as \"Purchase Receipt:Link/Purchase Receipt:120\",\n    `tabPurchase Receipt`.`supplier` as \"Supplier:Link/Supplier:120\",\n	`tabPurchase Receipt`.`supplier_name` as \"Supplier Name::150\",\n	`tabPurchase Receipt`.`posting_date` as \"Date:Date\",\n	`tabPurchase Receipt Item`.`project` as \"Project\",\n	`tabPurchase Receipt Item`.`item_code` as \"Item:Link/Item:120\",\n	(`tabPurchase Receipt Item`.`base_amount` - `tabPurchase Receipt Item`.`billed_amt`*ifnull(`tabPurchase Receipt`.conversion_rate, 1)) as \"Pending Amount:Currency:110\",\n	`tabPurchase Receipt Item`.`item_name` as \"Item Name::150\",\n	`tabPurchase Receipt Item`.`description` as \"Description::200\",\n	`tabPurchase Receipt`.`company` as \"Company:Link/Company:\"\nfrom `tabPurchase Receipt`, `tabPurchase Receipt Item`\nwhere\n    `tabPurchase Receipt`.name = `tabPurchase Receipt Item`.parent \n    and `tabPurchase Receipt`.docstatus = 1 \n    and `tabPurchase Receipt`.status != \"Closed\" \n    and `tabPurchase Receipt Item`.amount > 0\n    and `tabPurchase Receipt Item`.billed_amt < `tabPurchase Receipt Item`.amount\norder by `tabPurchase Receipt`.`name` desc',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Requested Items To Be Transferred','2013-05-13 16:23:05.000000','2017-02-24 20:07:57.880462','Administrator','Administrator',0,3,'Requested Items To Be Transferred','Stock Entry',NULL,'Yes','Stock',NULL,'Query Report',NULL,1,0,0,0,0,0,0,'select \n    mr.name as \"Material Request:Link/Material Request:120\",\n	mr.transaction_date as \"Date:Date:100\",\n	mr_item.item_code as \"Item Code:Link/Item:120\",\n	mr_item.qty as \"Qty:Float:100\",\n	mr_item.ordered_qty as \"Transferred Qty:Float:100\", \n	(mr_item.qty - ifnull(mr_item.ordered_qty, 0)) as \"Qty to Transfer:Float:100\",\n	mr_item.item_name as \"Item Name::150\",\n	mr_item.description as \"Description::200\",\n	mr.company as \"Company:Link/Company:\"\nfrom\n	`tabMaterial Request` mr, `tabMaterial Request Item` mr_item\nwhere\n	mr_item.parent = mr.name\n	and mr.material_request_type in (\"Material Transfer\", \"Material Issue\")\n	and mr.docstatus = 1\n	and mr.status != \"Stopped\"\n	and ifnull(mr_item.ordered_qty, 0) < ifnull(mr_item.qty, 0)\norder by mr.transaction_date asc',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
